# This is a reduced, verbatim-shaped sample of the SRT generated by the DJI
# aircraft supplied with this project.  Keep it inline: the tests must not
# depend on a removable WeChat attachment.
DJI_BRACKET_SRT = """1
00:00:00,000 --> 00:00:00,033
FrameCnt: 0 2026-08-19 16:20:16.562
[iso: 280] [shutter: 1/6400.0] [fnum: 2.8] [ev: 0] [color_md: default] [ae_meter_md: 1] [focal_len: 24.00] [dzoom_ratio: 1.00], [latitude: 30.836687] [longitude: 120.890825] [rel_alt: 70.105 abs_alt: 99.221] [gb_yaw: -102.9 gb_pitch: -1.0 gb_roll: 0.0] [dehaze_level: 0] [dehaze_mode: 0]

2
00:00:00,033 --> 00:00:00,067
FrameCnt: 1 2026-08-19 16:20:16.613
[iso: 270] [shutter: 1/5000.0] [fnum: 2.8] [ev: -0.3] [focal_len: 24.00] [dzoom_ratio: 1.20], [latitude: 30.836688] [longitude: 120.890826] [rel_alt: 70.095 abs_alt: 99.211] [gb_yaw: -103.0 gb_pitch: -16.4 gb_roll: 0.1]
"""


DJI_HTML_SRT = """1
00:00:01.250 --> 00:00:01.290
<font size="28">FrameCnt: 25, DiffTime: 40ms
2024-04-05 06:07:08.009
[iso : 100] [shutter : 1/800] [fnum : 4.0] [focal_len : 35.0]
[latitude : -33.865143] [longitude : 151.209900]
[rel_alt : 42.5 abs_alt : 77.25]
[aircraft_yaw : 12.5 aircraft_pitch : -2.5 aircraft_roll : 1.25]
[gb_yaw : 13.5 gb_pitch : -70.0 gb_roll : 0.5]</font>
"""


