class DJISubtitleParsingTests(unittest.TestCase):
    def test_utf8_bom_does_not_hide_the_first_cue(self) -> None:
        samples = extractor.parse_dji_srt("\ufeff" + DJI_BRACKET_SRT)
        self.assertEqual(len(samples), 2)
        self.assertEqual(samples[0].video_sample_index, 0)
        self.assertEqual(samples[0].frame_index, 0)

    def test_real_bracket_format_extracts_available_values(self) -> None:
        samples = extractor.parse_dji_srt(DJI_BRACKET_SRT, source_name="DJI_0001.SRT")
        self.assertEqual(len(samples), 2)

        first = samples[0].to_dict()
        self.assertEqual(first["frame_index"], 0)
        self.assertEqual(first["start_time_ms"], 0)
        self.assertEqual(first["end_time_ms"], 33)
        self.assertEqual(first["recorded_at"], "2026-08-19T16:20:16.562")
        self.assertAlmostEqual(first["latitude"], 30.836687)
        self.assertAlmostEqual(first["longitude"], 120.890825)
        self.assertEqual(first["position_crs"], "EPSG:4326")
        self.assertIn("horizontal only", first["field_sources"]["position_crs"])
        self.assertAlmostEqual(first["relative_altitude_m"], 70.105)
        self.assertAlmostEqual(first["absolute_altitude_m"], 99.221)
        self.assertEqual(first["iso"], 280)
        self.assertAlmostEqual(first["shutter_seconds"], 1 / 6400.0)
        self.assertAlmostEqual(first["aperture_f_number"], 2.8)
        # DJI's focal_len in this SRT is the 35 mm-equivalent focal length,
        # not a physical lens focal length.
        self.assertAlmostEqual(first["focal_length_35mm_equivalent_mm"], 24.0)
        self.assertAlmostEqual(first["digital_zoom_ratio"], 1.0)
        self.assertAlmostEqual(first["gimbal_yaw_deg"], -102.9)
        self.assertAlmostEqual(first["gimbal_pitch_deg"], -1.0)
        self.assertAlmostEqual(first["gimbal_roll_deg"], 0.0)
        # Unknown-but-verifiable DJI fields stay available losslessly even
        # before they receive a normalized schema field.
        self.assertEqual(first["extra_fields"]["dehaze_level"], "0")
        self.assertEqual(first["extra_fields"]["dehaze_mode"], "0")

        # DJI's gb_* fields describe the gimbal.  Treating them as aircraft
        # attitude silently rotates every ground ray and is a severe AR error.
        self.assertNotIn("aircraft_yaw_deg", first)
        self.assertNotIn("aircraft_pitch_deg", first)
        self.assertNotIn("aircraft_roll_deg", first)
        self.assertEqual(first["field_sources"]["gimbal_yaw_deg"], "srt.gb_yaw")

    def test_html_wrapped_format_keeps_body_and_gimbal_attitudes_separate(self) -> None:
        [sample] = extractor.parse_dji_srt(DJI_HTML_SRT)
        wire = sample.to_dict()
        self.assertEqual(wire["frame_index"], 25)
        self.assertEqual(wire["start_time_ms"], 1_250)
        self.assertEqual(wire["end_time_ms"], 1_290)
        self.assertAlmostEqual(wire["aircraft_yaw_deg"], 12.5)
        self.assertAlmostEqual(wire["aircraft_pitch_deg"], -2.5)
        self.assertAlmostEqual(wire["aircraft_roll_deg"], 1.25)
        self.assertAlmostEqual(wire["gimbal_yaw_deg"], 13.5)
        self.assertAlmostEqual(wire["gimbal_pitch_deg"], -70.0)
        self.assertAlmostEqual(wire["gimbal_roll_deg"], 0.5)

    def test_legacy_gps_tuple_format_is_supported(self) -> None:
        legacy = """1
00:00:02,000 --> 00:00:02,040
<font size="28">FrameCnt: 50, DiffTime: 40ms
GPS(22.581234, 113.966789, 58.75)
[iso: 100] [gb_yaw: -20 gb_pitch: -90 gb_roll: 0]</font>
"""
        [sample] = extractor.parse_dji_srt(legacy, source_name="legacy.SRT")
        wire = sample.to_dict()
        self.assertAlmostEqual(wire["latitude"], 22.581234)
        self.assertAlmostEqual(wire["longitude"], 113.966789)
        self.assertEqual(wire["position_crs"], "EPSG:4326")
        self.assertAlmostEqual(wire["gps_altitude_m"], 58.75)
        self.assertEqual(wire["frame_delta_ms"], 40.0)
        self.assertEqual(wire["source"], {"kind": "sidecar_srt", "name": "legacy.SRT"})

    def test_missing_fields_are_omitted_instead_of_fabricated(self) -> None:
        minimal = """1
00:00:00,500 --> 00:00:00,540
FrameCnt: 12
[iso: 200]
"""
        [sample] = extractor.parse_dji_srt(minimal)
        wire = sample.to_dict()
        self.assertEqual(wire["frame_index"], 12)
        self.assertEqual(wire["iso"], 200)
        self.assertNotIn("latitude", wire)
        self.assertNotIn("longitude", wire)
        self.assertNotIn("position_crs", wire)
        self.assertNotIn("gimbal_yaw_deg", wire)
        self.assertNotIn("aircraft_yaw_deg", wire)
        self.assertNotIn("recorded_at", wire)
        self.assertIn("latitude", wire["missing_fields"])
        self.assertIn("longitude", wire["missing_fields"])

    def test_cue_times_and_capture_clock_are_preserved_independently(self) -> None:
        samples = extractor.parse_dji_srt(DJI_BRACKET_SRT)
        first, second = (sample.to_dict() for sample in samples)
        self.assertEqual((first["start_time_ms"], first["end_time_ms"]), (0, 33))
        self.assertEqual((second["start_time_ms"], second["end_time_ms"]), (33, 67))
        self.assertEqual(second["frame_index"], 1)
        self.assertEqual(second["recorded_at"], "2026-08-19T16:20:16.613")
        self.assertEqual(second["field_sources"]["start_time_ms"], "srt.timecode.start")
        self.assertIn("timezone not present", second["field_sources"]["recorded_at"])

    def test_sample_order_stays_contiguous_when_dji_framecnt_has_gaps(self) -> None:
        # The supplied 3467-cue DJI recording skips FrameCnt 1231, 1607 and
        # 3240.  Downstream code needs both the original counter and a stable
        # zero-based subtitle sample index.
        gapped = DJI_BRACKET_SRT.replace("FrameCnt: 1 ", "FrameCnt: 3 ")
        samples = [sample.to_dict() for sample in extractor.parse_dji_srt(gapped)]
        self.assertEqual([sample["video_sample_index"] for sample in samples], [0, 1])
        self.assertEqual([sample["frame_index"] for sample in samples], [0, 3])
        self.assertEqual(
            samples[1]["field_sources"]["video_sample_index"],
            "parser.source_order (not FrameCnt)",
        )
        # 30000/1001 fps has a 33.366... ms period.  SRT millisecond cue
        # rounding must remain within half a millisecond of that PTS grid.
        frame_period_ms = 1000 * 1001 / 30000
        for index, sample in enumerate(samples):
            self.assertLessEqual(abs(sample["start_time_ms"] - index * frame_period_ms), 0.5)

    def test_bad_srt_timecode_is_rejected(self) -> None:
        malformed = """1
not-a-time --> 00:00:00,033
FrameCnt: 0 [latitude: 30.0] [longitude: 120.0]
"""
        with self.assertRaises(extractor.SubtitleParseError):
            extractor.parse_dji_srt(malformed, source_name="broken.srt")

    def test_out_of_range_coordinates_are_rejected(self) -> None:
        invalid_gps = """1
00:00:00,000 --> 00:00:00,033
FrameCnt: 0 [latitude: 130.0] [longitude: 220.0] [rel_alt: 10 abs_alt: 20]
"""
        with self.assertRaises(extractor.SubtitleParseError):
            extractor.parse_dji_srt(invalid_gps)


class DJIProbeAndExtractionTests(unittest.TestCase):
    def test_opencv_fallback_preserves_rotation_codec_and_bitrate_metadata(self) -> None:
        properties = {
            1: 3840.0,
            2: 2160.0,
            3: 29.97,
            4: 300.0,
            5: 90.0,
            6: float(sum(ord(character) << (8 * index) for index, character in enumerate("hvc1"))),
            7: 80_000.0,
        }

        class FakeCapture:
            def isOpened(self) -> bool:
                return True

            def get(self, property_id: int) -> float:
                return properties[property_id]

            def release(self) -> None:
                return None

        fake_cv2 = SimpleNamespace(
            CAP_PROP_FRAME_WIDTH=1,
            CAP_PROP_FRAME_HEIGHT=2,
            CAP_PROP_FPS=3,
            CAP_PROP_FRAME_COUNT=4,
            CAP_PROP_ORIENTATION_META=5,
            CAP_PROP_FOURCC=6,
            CAP_PROP_BITRATE=7,
            VideoCapture=lambda _path: FakeCapture(),
        )
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "rotated.mp4"
            video.write_bytes(b"fixture")
            with patch.dict("sys.modules", {"cv2": fake_cv2}):
                metadata = extractor._opencv_video_metadata(video)

        self.assertEqual(metadata.rotation_deg, 90.0)
        self.assertEqual(metadata.video_codec, "hvc1")
        self.assertEqual(metadata.bit_rate_bps, 80_000_000)
        self.assertEqual(metadata.field_sources["rotation_deg"], "opencv.CAP_PROP_ORIENTATION_META")

    def test_ffprobe_telemetry_preserves_zero_pts_for_first_frame(self) -> None:
        document = {
            "frames": [
                {
                    "stream_index": 0,
                    "best_effort_timestamp_time": "0.000000",
                    "duration_time": "0.033367",
                    "coded_picture_number": 0,
                    "tags": {
                        "latitude": "30.1",
                        "longitude": "120.2",
                        "gb_pitch": "-90.0",
                    },
                }
            ]
        }
        [sample] = extractor.parse_ffprobe_telemetry(document)
        wire = sample.to_dict()
        self.assertEqual(wire["video_sample_index"], 0)
        self.assertEqual(wire["start_time_ms"], 0)
        self.assertEqual(wire["end_time_ms"], 33)
        self.assertEqual(wire["frame_index"], 0)
        self.assertEqual(wire["gimbal_pitch_deg"], -90.0)
        self.assertEqual(wire["position_crs"], "EPSG:4326")
        self.assertNotIn("aircraft_pitch_deg", wire)

    def test_ffprobe_document_extracts_video_contract(self) -> None:
        metadata = extractor.parse_ffprobe_document(FFPROBE_DOCUMENT).to_dict()
        self.assertEqual(metadata["width"], 3840)
        self.assertEqual(metadata["height"], 2160)
        self.assertEqual(metadata["video_codec"], "hevc")
        self.assertAlmostEqual(metadata["frame_rate_fps"], 30_000 / 1_001)
        self.assertEqual(metadata["frame_count"], 60)
        self.assertAlmostEqual(metadata["duration_ms"], 2002.0)
        self.assertEqual(metadata["format_tags"]["com.apple.quicktime.make"], "DJI")
        self.assertEqual(metadata["format_tags"]["com.apple.quicktime.model"], "FC8482")
        self.assertEqual(metadata["format_info"]["filename"], "DJI_0001.MP4")
        self.assertEqual(
            [stream["index"] for stream in metadata["streams"] if stream["codec_type"] == "subtitle"],
            [2],
        )
        self.assertEqual(metadata["field_sources"]["frame_rate_fps"], "streams[video].avg_frame_rate/r_frame_rate")
        self.assertIn("pixel_format", metadata["missing_fields"])

    def test_ffprobe_document_without_video_stream_is_rejected(self) -> None:
        with self.assertRaises(extractor.ExtractionError):
            extractor.parse_ffprobe_document({"format": {}, "streams": []})

    def test_output_contract_includes_lineage_and_missing_field_report(self) -> None:
        with tempfile.TemporaryDirectory() as temporary_directory:
            root = Path(temporary_directory)
            video = root / "DJI_0001.MP4"
            subtitle = root / "DJI_0001.SRT"
            video.write_bytes(b"not-decoded-when-ffprobe-json-is-supplied")
            subtitle.write_text(DJI_BRACKET_SRT, encoding="utf-8")

            result = extractor.extract_dji_video(
                video,
                srt_path=subtitle,
                ffprobe_json=FFPROBE_DOCUMENT,
                extract_embedded_subtitles=False,
            ).to_dict()

        self.assertEqual(result["schema_version"], extractor.SCHEMA_VERSION)
        self.assertEqual(Path(result["source"]["video_file"]).name, "DJI_0001.MP4")
        self.assertEqual(Path(result["subtitle_sources"][0]["name"]).name, "DJI_0001.SRT")
        self.assertEqual(result["subtitle_sources"][0]["kind"], "sidecar_srt")
        self.assertEqual(len(result["telemetry"]), 2)
        self.assertIn("field_sources", result["video"])
        self.assertIn("missing_fields", result["video"])
        self.assertIn("field_sources", result["telemetry"][0])
        self.assertIn("missing_fields", result["telemetry"][0])
        self.assertEqual(result["telemetry_coverage"]["sample_count"], 2)
        self.assertIsInstance(result["warnings"], list)
        # The contract must remain JSON serialisable for the Cesium loader.
        json.dumps(result, ensure_ascii=False, allow_nan=False)

    def test_missing_video_input_is_rejected(self) -> None:
        with tempfile.TemporaryDirectory() as temporary_directory:
            missing = Path(temporary_directory) / "missing.mp4"
            with self.assertRaises(extractor.ExtractionError):
                extractor.extract_dji_video(missing, ffprobe_json=FFPROBE_DOCUMENT)

    def test_probe_video_distinguishes_missing_ffprobe_binary(self) -> None:
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0001.MP4"
            video.write_bytes(b"video")
            with patch.object(extractor.shutil, "which", return_value=None):
                with self.assertRaises(extractor.FFprobeNotFoundError):
                    extractor.probe_video(video, ffprobe_bin="missing-ffprobe")

    def test_probe_video_cancellation_terminates_the_active_process_tree(self) -> None:
        cancel_event = threading.Event()

        class WaitingProcess:
            pid = 4242
            returncode = None
            stdout = None
            stderr = None

            @staticmethod
            def poll() -> None:
                return None

            @staticmethod
            def communicate(*, timeout: float) -> tuple[bytes, bytes]:
                cancel_event.set()
                raise subprocess.TimeoutExpired(["ffprobe"], timeout)

        process = WaitingProcess()
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0001.MP4"
            video.write_bytes(b"video")
            with (
                patch.object(extractor, "_resolve_binary", return_value="ffprobe.exe"),
                patch.object(extractor.subprocess, "Popen", return_value=process) as popen,
                patch.object(extractor, "_terminate_process_tree") as terminate,
            ):
                with self.assertRaises(extractor.ExtractionCancelled):
                    extractor.probe_video(video, cancel_event=cancel_event)

        popen.assert_called_once()
        terminate.assert_called_once_with(process)

    def test_cancel_callback_is_checked_before_starting_ffprobe(self) -> None:
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0001.MP4"
            video.write_bytes(b"video")
            with (
                patch.object(extractor, "_resolve_binary", return_value="ffprobe.exe"),
                patch.object(extractor.subprocess, "Popen") as popen,
            ):
                with self.assertRaises(extractor.ExtractionCancelled):
                    extractor.probe_video(video, cancel_callback=lambda: True)

        popen.assert_not_called()

    def test_cancellation_wins_if_requested_while_ffprobe_is_finishing(self) -> None:
        cancel_event = threading.Event()

        class FinishingProcess:
            pid = 4343
            returncode = 0
            stdout = None
            stderr = None

            @staticmethod
            def poll() -> int:
                return 0

            @staticmethod
            def communicate(*, timeout: float) -> tuple[bytes, bytes]:
                del timeout
                cancel_event.set()
                return b'{"format": {}, "streams": []}', b""

        process = FinishingProcess()
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0001.MP4"
            video.write_bytes(b"video")
            with (
                patch.object(extractor, "_resolve_binary", return_value="ffprobe.exe"),
                patch.object(extractor.subprocess, "Popen", return_value=process),
                patch.object(extractor, "_terminate_process_tree") as terminate,
            ):
                with self.assertRaises(extractor.ExtractionCancelled):
                    extractor.probe_video(video, cancel_event=cancel_event)

        terminate.assert_called_once_with(process)

    @unittest.skipUnless(extractor.os.name == "nt", "Windows taskkill contract")
    def test_windows_termination_uses_taskkill_for_the_whole_tree(self) -> None:
        process = Mock(pid=7788, stdout=None, stderr=None)
        process.poll.return_value = None
        process.wait.return_value = 0
        taskkill = Mock()
        taskkill.wait.return_value = 0
        with patch.object(extractor.subprocess, "Popen", return_value=taskkill) as popen:
            extractor._terminate_process_tree(process)

        command = popen.call_args.args[0]
        self.assertEqual(command, ["taskkill", "/PID", "7788", "/T", "/F"])
        process.wait.assert_called_once_with(timeout=1)

    @unittest.skipUnless(extractor.os.name == "nt", "Windows taskkill contract")
    def test_windows_termination_falls_back_immediately_if_taskkill_is_denied(self) -> None:
        process = Mock(pid=7799, stdout=None, stderr=None)
        process.poll.return_value = None
        process.wait.return_value = 0
        taskkill = Mock()
        taskkill.wait.return_value = 1
        with patch.object(extractor.subprocess, "Popen", return_value=taskkill):
            extractor._terminate_process_tree(process)

        process.kill.assert_called_once_with()
        process.wait.assert_called_once_with(timeout=1)

    def test_extract_propagates_probe_cancellation_without_opencv_fallback(self) -> None:
        cancel_event = threading.Event()
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0002.MP4"
            video.write_bytes(b"video")
            with (
                patch.object(
                    extractor,
                    "probe_video",
                    side_effect=extractor.ExtractionCancelled("cancelled"),
                ) as probe,
                patch.object(extractor, "_opencv_video_metadata") as opencv,
            ):
                with self.assertRaises(extractor.ExtractionCancelled):
                    extractor.extract_dji_video(
                        video,
                        cancel_event=cancel_event,
                        extract_embedded_subtitles=False,
                    )

        self.assertIs(probe.call_args.kwargs["cancel_event"], cancel_event)
        self.assertIsNone(probe.call_args.kwargs["cancel_callback"])
        opencv.assert_not_called()

    def test_extract_propagates_embedded_ffmpeg_cancellation(self) -> None:
        cancel_event = threading.Event()
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0003.MP4"
            video.write_bytes(b"video")
            with patch.object(
                extractor,
                "_extract_embedded_srt",
                side_effect=extractor.ExtractionCancelled("cancelled"),
            ) as embedded:
                with self.assertRaises(extractor.ExtractionCancelled):
                    extractor.extract_dji_video(
                        video,
                        ffprobe_json=FFPROBE_DOCUMENT,
                        cancel_event=cancel_event,
                    )

        self.assertIs(embedded.call_args.kwargs["cancel_event"], cancel_event)
        self.assertIsNone(embedded.call_args.kwargs["cancel_callback"])

    def test_full_extraction_falls_back_to_opencv_when_ffprobe_is_missing(self) -> None:
        fallback = extractor.VideoMetadata(
            backend="opencv",
            width=1920,
            height=1080,
            frame_rate_fps=29.97,
            frame_count=300,
            duration_ms=10_010,
            field_sources={"width": "opencv.CAP_PROP_FRAME_WIDTH"},
            missing_fields=("video_codec",),
        )
        with tempfile.TemporaryDirectory() as temporary_directory:
            video = Path(temporary_directory) / "DJI_0002.MP4"
            video.write_bytes(b"video")
            with (
                patch.object(
                    extractor,
                    "probe_video",
                    side_effect=extractor.FFprobeNotFoundError("ffprobe unavailable"),
                ),
                patch.object(extractor, "_opencv_video_metadata", return_value=fallback) as opencv,
            ):
                result = extractor.extract_dji_video(
                    video,
                    extract_embedded_subtitles=False,
                ).to_dict()

        opencv.assert_called_once()
        self.assertEqual(result["video"]["backend"], "opencv")
        self.assertEqual(result["video"]["width"], 1920)
        self.assertTrue(any("OpenCV" in warning for warning in result["warnings"]))


